contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newAlloSettings, address payable newRoundImplementation) public payable {
        address beforeAlloSettings = c.alloSettings();
        address beforeRoundImplementation = c.roundImplementation();

        bool alloReverted;
        try c.updateAlloSettings(newAlloSettings) {
            alloReverted = false;
        } catch {
            alloReverted = true;
        }

        if (alloReverted) {
            assert(c.alloSettings() == beforeAlloSettings);
        } else {
            assert(c.alloSettings() == newAlloSettings);
        }

        bool roundReverted;
        try c.updateRoundImplementation(newRoundImplementation) {
            roundReverted = false;
        } catch {
            roundReverted = true;
        }

        if (roundReverted) {
            assert(c.roundImplementation() == beforeRoundImplementation);
        } else {
            assert(c.roundImplementation() == newRoundImplementation);
        }
    }

    receive() external payable {}
}

